   308	function checkpointDetails(input: CheckpointActiveTaskInput["task"]): string {
   309	  const lines =
   310	    input.state === "clear"
   311	      ? [`Task checkpoint: clear`, `Outcome: ${input.outcome}`]
   312	      : [`Task checkpoint: ${input.state}`, `Next step: ${input.nextStep}`];
   313	  if (input.details) lines.push("", input.details);
   314	  return lines.join("\n");
   315	}
   316	
   317	function checkpointEventMatches(
   318	  event: ContinuityEvent,
   319	  task: CheckpointActiveTaskInput["task"],
   320	  details: string,
   321	): boolean {
   322	  const expectedType = task.state === "clear" ? "correction" : "next_action";
   323	  const expectedSummary = task.state === "clear" ? task.outcome : task.summary;
   324	  return event.type === expectedType && event.summary === expectedSummary && event.details === details;
