async function runContextHook(): Promise<void> {
  let input: CodexHookInput = {};
  const text = await readStdin();
  if (text.trim().length > 0) {
    try {
      input = JSON.parse(text);
    } catch {
      input = {};
    }
  }

  const cwd = typeof input.cwd === "string" && input.cwd.trim().length > 0 ? input.cwd : process.cwd();
  const hookEventName = input.hook_event_name ?? "SessionStart";
  if (hookEventName === "PreToolUse") {
    if (isDirectCodexContextHookProbe(input.tool_name, input.tool_input)) {
      const reason =
        "HOST_LIFECYCLE_PROBE_BLOCKED: Agent-issued Codex lifecycle-hook probes are forbidden. Use the context injected by the registered host hook.";
      process.stderr.write(`[anvil codex hook] ${reason}\n`);
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
    const toolName = workContextBoundToolName(input.tool_name);
    if (!toolName) {
      return;
    }
    if (!isRecord(input.tool_input)) {
      const reason = "WORK_CONTEXT_MISMATCH: Anvil mutation tool input must be an object";
      await tryRecordHookRejection("WORK_CONTEXT_MISMATCH", toolName);
      process.stderr.write(`[anvil work context] ${reason}\n`);
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
    try {
      const binding = await refreshCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
      let trustedInput = stripCallerMutationAuthority(input.tool_input, toolName);
    const promptContext = [envelope.markdown, workContextDiagnostic]
      .filter((value) => value.length > 0)
      .join("\n\n");
    process.stdout.write(`${JSON.stringify(codexAdditionalContext("UserPromptSubmit", promptContext))}\n`);
    return;
  }
  if (hookEventName !== "SessionStart") {
    fail("anvil codex context-hook supports only SessionStart, UserPromptSubmit, PreToolUse, and Stop hook events");
  }

  let binding;
  try {
    binding = await bindCodexWorkContext({
      cwd: input.cwd,
