   327	export async function checkpointActiveTask(
   328	  input: CheckpointActiveTaskInput,
   329	): Promise<CheckpointActiveTaskOutput> {
   330	  const checkpointId = input.checkpointId.trim();
   331	  if (checkpointId.length === 0 || checkpointId.length > 200) {
   332	    throw new ContinuityServiceError("VALIDATION_ERROR", "checkpointId must contain between 1 and 200 characters");
   333	  }
