   375	    }
   376	    if (input.task.state === "clear" && before.kind === "ok" && before.value.active_task === null && !existing) {
   377	      throw new ContinuityServiceError("VALIDATION_ERROR", "No active task is available to clear");
   378	    }
   379	
   380	    const priorTask = before.kind === "ok" ? before.value.active_task : null;
   381	    const eventInput: EventInput = {
   382	      type: input.task.state === "clear" ? "correction" : "next_action",
   383	      status: "active",
   384	      summary: input.task.state === "clear" ? input.task.outcome : input.task.summary,
   385	      details,
   386	      supersedes:
   387	        input.task.state !== "clear" && priorTask && priorTask.event_id !== eventId ? [priorTask.event_id] : [],
   388	      resolves: input.task.state === "clear" && priorTask ? [priorTask.event_id] : [],
   389	      related_events: priorTask ? [priorTask.event_id] : [],
   390	    };
   391	    const event =
   392	      existing ??
   393	      (await recordEvent(paths, eventInput, {
   394	        source: boundEventSource(input.binding, input.source),
   395	        now: input.now,
   396	        id: () => eventId,
   397	      }));
   398	
   399	    const afterRecord = await readCurrent(paths);
   400	    if (afterRecord.kind !== "ok") {
   401	      throw new ContinuityServiceError("CONTINUITY_MALFORMED", afterRecord.message);
   402	    }
   403	    const desired: ActiveTask | null =
   404	      input.task.state === "clear"
   405	        ? null
   406	        : activeTaskSchema.parse({
   407	            event_id: event.id,
   408	            recorded_at: event.effective_at ?? event.created_at,
   409	            summary: input.task.summary,
   410	            state: input.task.state,
   411	            next_step: input.task.nextStep,
   412	          });
   413	    const taskChanged = JSON.stringify(afterRecord.value.active_task) !== JSON.stringify(desired);
   414	    const nextInput = currentFrameInput(afterRecord.value);
   415	    nextInput.active_task = desired;
   416	    nextInput.next_actions = nextInput.next_actions.filter((item) => item.event_id !== event.id);
   417	    const changed = taskChanged || nextInput.next_actions.length !== afterRecord.value.next_actions.length;
   418	    const frame = changed
   419	      ? await updateCurrent(paths, nextInput, { now: input.now })
   420	      : afterRecord.value;
   421	
   422	    return {
   423	      paths,
   424	      workspace: paths.workspace,
   425	      event,
   426	      frame,
   427	      rendered: renderContinuityFrame(frame),
   428	      changed,
   429	      binding: workContextBindingView(input.binding),
   430	    };
   343	export async function recordEvent(
   344	  paths: ContinuityPaths,
   345	  input: EventInput,
   346	  options: {
   347	    source?: EventSource;
   348	    now?: Clock;
   349	    id?: IdGenerator;
   350	  } = {},
   351	): Promise<ContinuityEvent> {
   352	  return withWorkspaceMutationLock(paths, () => recordEventUnlocked(paths, input, options), { now: options.now });
   353	}
