   355	async function recordEventUnlocked(
   356	  paths: ContinuityPaths,
   357	  input: EventInput,
   358	  options: {
   359	    source?: EventSource;
   360	    now?: Clock;
   361	    id?: IdGenerator;
   362	  } = {},
   363	): Promise<ContinuityEvent> {
   364	  const eventInput = ensureEventInput(input);
   365	  const eventId = (options.id ?? newEventId)();
   366	  const now = (options.now ?? nowIso)();
   367	  const source = ensureEventSource(options.source ?? { kind: "manual" });
   368	
   369	  const current = await readCurrent(paths);
   370	  let currentFrame: CurrentFrame;
   371	  if (current.kind === "ok") {
   372	    currentFrame = current.value;
   373	  } else if (current.kind === "missing") {
   374	    currentFrame = await initWorkspaceUnlocked(paths, bootstrapFrameInput(eventInput, eventId, now), { now: () => now });
   375	  } else {
   376	    throw new Error(`Cannot record event without valid current frame: ${current.message}`);
   377	  }
   378	
   379	  await writeFile(paths.eventsPath, "", { encoding: "utf8", flag: "a" });
   380	  const event: ContinuityEvent = {
   381	    version: EVENT_SCHEMA_VERSION,
   382	    id: eventId,
   383	    created_at: now,
   384	    effective_at: now,
   385	    ...eventInput,
   386	    workspace: currentFrame.workspace,
   387	    source,
   388	  };
   389	
   390	  await appendJsonLine(paths.eventsPath, event);
   391	  return event;
   392	}
