   394	export async function updateCurrent(
   395	  paths: ContinuityPaths,
   396	  input: CurrentFrameInput,
   397	  options: { now?: Clock } = {},
   398	): Promise<CurrentFrame> {
   399	  return withWorkspaceMutationLock(paths, () => updateCurrentUnlocked(paths, input, options), { now: options.now });
   400	}
   401	
   402	async function updateCurrentUnlocked(
   403	  paths: ContinuityPaths,
   404	  input: CurrentFrameInput,
   405	  options: { now?: Clock } = {},
   406	): Promise<CurrentFrame> {
   407	  const current = await readCurrent(paths);
   408	  if (current.kind !== "ok") throw new Error(`Cannot update current frame: ${current.message}`);
   409	
   410	  const frameInput = ensureCurrentInput(input);
   411	  const next: CurrentFrame = {
   412	    version: CURRENT_SCHEMA_VERSION,
   413	    updated_at: (options.now ?? nowIso)(),
   414	    workspace: current.value.workspace,
   415	    ...frameInput,
   416	    active_task: frameInput.active_task ?? null,
   417	  };
   418	  await writeJsonAtomic(paths.currentPath, next);
   419	  return next;
   420	}
